import pickle,numpy as np
from scipy.optimize import least_squares
from calibrate_retraction import _force_stages,_hold_rate
cases=pickle.load(open('public_specimens.pkl','rb'))
def extract(s,c):
 t,f,h=(c[k] for k in ('time_s','force_N','raw_disp_um')); h=h-f*s['c_frame']; a,b=_force_stages(f); v,noise=_hold_rate(t,h,a,b)
 z=t[b+1:]-t[b]; x=f[b+1:]-f[b]; y=h[b+1:]; k=z>.015
 return z[k],x[k],y[k]-np.median(y[k]),v,noise
for shape in ('pulse','sat','damped','gamma','pulse_sat'):
 for power in (2,3,4):
  print(shape,power)
  for s in cases:
   vals=[]
   for c in s['curves']:
    z,x,y,v,noise=extract(s,c)
    def fit(p):
     off,k,lt,dr=p[:4]; tau=np.exp(lt); w=z/tau
     if shape=='pulse': q=z*np.exp(-w)
     elif shape=='sat': q=-tau*np.expm1(-w)
     elif shape=='damped': q=tau*np.exp(-w)*np.sin(w)
     elif shape=='gamma': q=z*np.exp(-w*w)
     else: q=z*np.exp(-w)+p[4]*tau*(1-(1+w)*np.exp(-w))
     return off+k*x+v*q+dr*(z/z[-1])**power-y
    ps=[]
    for tau in (.1,.3,.8):
     p=[y[0],.07,np.log(tau),.02]+([0.] if shape=='pulse_sat' else [])
     lo=[-np.inf,1e-6,np.log(.003),0]+([-2.] if shape=='pulse_sat' else []); hi=[np.inf,1,np.log(3),np.inf]+([2.] if shape=='pulse_sat' else [])
     ps.append(least_squares(fit,p,bounds=(lo,hi),loss='soft_l1',f_scale=noise))
    opt=min(ps,key=lambda p:p.cost); vals.append((round(1/opt.x[1],2),round(np.exp(opt.x[2]),3),round(opt.x[3],4),round(np.median(abs(opt.fun)),4)))
   print(s['id'],vals)
